#include <stdio.h>
#include <string.h>
#include <ctype.h>

static int soundex_digit(char c)
{
    c = (char)toupper((unsigned char)c);
    switch (c) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T': return 3;
        case 'L': return 4;
        case 'M': case 'N': return 5;
        case 'R': return 6;
        default: return 0;
    }
}

int main(int argc, char *argv[])
{
    const char *input;
    char result[5];
    int prev_digit, digit;
    int out_idx = 0;

    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    input = argv[1];
    if (input[0] == '\0') {
        puts("EMPTY");
        return 0;
    }
    result[0] = input[0];
    prev_digit = soundex_digit(input[0]);
    for (size_t i = 1; input[i] != '\0' && out_idx < 3; ++i) {
        digit = soundex_digit(input[i]);
        if (digit == 0) continue;
        if (digit == prev_digit) continue;
        result[1 + out_idx] = (char)('0' + digit);
        ++out_idx;
        prev_digit = digit;
    }
    while (out_idx < 3) {
        result[1 + out_idx] = '0';
        ++out_idx;
    }
    result[4] = '\0';
    puts(result);
    return 0;
}
